const KEY='durga-dairy-v2-db';
const CLOUD_API=(window.DURGA_CONFIG&&window.DURGA_CONFIG.apiBase)||'';
let cloudState={status:CLOUD_API?'connecting':'local',lastSync:null,error:null};
const SYNC_ARRAYS=['users','prices','sales','collections','milk','stockPurchases','stockUsage','expenses','customers','vendors','cashChecks','audit','customerSales','customerPayments','customerBills'];
function mergeCloudDB(local,remote){
  const base=structuredClone?structuredClone(defaultDB):JSON.parse(JSON.stringify(defaultDB));
  const out=Object.assign(base,remote||{},local||{});
  for(const key of SYNC_ARRAYS){
    const lm=Array.isArray(local?.[key])?local[key]:[];
    const rm=Array.isArray(remote?.[key])?remote[key]:[];
    const map=new Map();
    for(const x of rm)if(x?.id!=null)map.set(String(x.id),x);
    for(const x of lm)if(x?.id!=null)map.set(String(x.id),x);
    const noId=[...rm.filter(x=>x?.id==null),...lm.filter(x=>x?.id==null)];
    out[key]=[...map.values(),...noId];
  }
  out.currentUser=local?.currentUser||remote?.currentUser||null;
  out.version=Math.max(num(local?.version),num(remote?.version),2);
  return out;
}
async function cloudSync(){
  if(!CLOUD_API||!db.currentUser)return;
  try{
    cloudState.status='syncing';
    const base=CLOUD_API.replace(/\/$/,'');
    const token=localStorage.getItem('durga-token')||'';
    const headers={'Content-Type':'application/json','Authorization':'Bearer '+token};
    const stateRes=await fetch(base+'/api/state',{headers});
    if(!stateRes.ok)throw new Error('Cloud read failed ('+stateRes.status+')');
    const state=await stateRes.json();
    const remote=state.db||null;
    if(remote){
      const currentUser=db.currentUser;
      db=mergeCloudDB(db,remote);
      db.currentUser=currentUser;
      localStorage.setItem(KEY,JSON.stringify(db));
    }
    const push=await fetch(base+'/api/sync',{
      method:'POST',headers,
      body:JSON.stringify({workspaceId:'durga-dairy',db})
    });
    if(!push.ok)throw new Error('Cloud write failed ('+push.status+')');
    const j=await push.json();
    if(j.db){
      const currentUser=db.currentUser;
      db=mergeCloudDB(db,j.db);
      db.currentUser=currentUser;
      localStorage.setItem(KEY,JSON.stringify(db));
    }
    cloudState={status:'online',lastSync:new Date().toISOString(),error:null};
  }catch(e){
    cloudState={status:'offline',lastSync:cloudState.lastSync,error:e.message};
  }
}
async function cloudPull(){
  if(!CLOUD_API||!db.currentUser)return false;
  try{
    const base=CLOUD_API.replace(/\/$/,'');
    const token=localStorage.getItem('durga-token')||'';
    const r=await fetch(base+'/api/state',{headers:{'Authorization':'Bearer '+token,'Cache-Control':'no-cache'}});
    if(!r.ok)throw new Error('Cloud read failed ('+r.status+')');
    const j=await r.json();
    if(j.db){
      const currentUser=db.currentUser;
      db=mergeCloudDB(db,j.db);
      db.currentUser=currentUser;
      localStorage.setItem(KEY,JSON.stringify(db));
      cloudState={status:'online',lastSync:new Date().toISOString(),error:null};
      return true;
    }
    cloudState={status:'online',lastSync:new Date().toISOString(),error:null};
    return false;
  }catch(e){
    cloudState={status:'offline',lastSync:cloudState.lastSync,error:e.message};
    return false;
  }
}
function scheduleCloudSync(){clearTimeout(window.__durgaSyncTimer);window.__durgaSyncTimer=setTimeout(cloudSync,500);}
function startCloudRealtimeSync(){
  clearInterval(window.__durgaRealtimeTimer);
  if(!CLOUD_API)return;
  window.__durgaRealtimeTimer=setInterval(async()=>{
    if(!db.currentUser||document.hidden)return;
    const changed=await cloudPull();
    if(changed&&document.getElementById('root')?.querySelector('.app')){try{render(document.querySelector('.nav button.active')?.getAttribute('onclick')?.match(/render\('([^']+)'/)?.[1]||'dashboard')}catch(e){}}
  },3000);
}
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+Math.random();
const now=()=>new Date(); const iso=()=>now().toISOString().slice(0,10); const ym=d=>String(d||'').slice(0,7); const fmtDate=d=>{const [y,m,day]=String(d||'').slice(0,10).split('-'); return day&&m&&y?`${day}-${m}-${y}`:String(d||'')}; const filterDate=(d,mode='all',value='')=>{if(!value||mode==='all')return true; if(mode==='year')return String(d).slice(0,4)===value; if(mode==='month')return String(d).slice(0,7)===value; return String(d)===value};
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const num=n=>Number(n||0); const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
const defaultDB={version:2,users:[{id:'u_owner',name:'Hiren',email:'owner@durga.local',pin:'1234',role:'Owner',active:true},{id:'u_brother',name:'Brother',email:'brother@durga.local',pin:'3333',role:'Full Access Member',active:true},{id:'u_family',name:'Family Member',email:'family@durga.local',pin:'1111',role:'Family Member',active:true},{id:'u_staff',name:'Dairy Staff',email:'staff@durga.local',pin:'2222',role:'Staff',active:true}],currentUser:null,settings:{cowRate:72,buffaloRate:68,gheeBuyRate:1050,gheeSaleRate:0,pedaBuyRate:180,pedaSaleRate:0,salePrices:{milk82:82,milk72:72,buttermilk:30,ghee:1100,peda:400}},prices:[],sales:[],collections:[],milk:[],stockPurchases:[],stockUsage:[],expenses:[],customers:[],vendors:[],cashChecks:[],audit:[],customerSales:[],customerPayments:[],customerBills:[]};
let db=load();
function load(){try{return Object.assign(defaultDB,JSON.parse(localStorage.getItem(KEY)||'{}'))}catch(e){return structuredClone?structuredClone(defaultDB):JSON.parse(JSON.stringify(defaultDB))}}
function ensureSalesConfig(){db.settings=db.settings||{};db.settings.salePrices=Object.assign({milk:72,buttermilk:30,ghee:1100,peda:400},db.settings.salePrices||{});if(db.settings.salePrices.milk==null)db.settings.salePrices.milk=72;db.sales=(db.sales||[]).map(x=>{if(x.saleKey==='milk82'||x.saleKey==='milk72'||x.product==='Milk'){x.saleKey='milk';x.product='Milk'}if(!x.rate&&x.qty)x.rate=num(x.amount)/num(x.qty);return x});db.customers=(db.customers||[]).map(x=>{if(!x.saleKey&&x.product)x.saleKey=String(x.product).toLowerCase()==='milk'?'milk':String(x.product).toLowerCase()==='buttermilk'?'buttermilk':String(x.product).toLowerCase()==='ghee'?'ghee':String(x.product).toLowerCase()==='peda'?'peda':'other';if(!x.priceHistory&&x.rate)x.priceHistory=[{date:x.createdAt?String(x.createdAt).slice(0,10):iso(),rate:num(x.rate)}];return x})}
ensureSalesConfig();
function saleProducts(){return [{key:'milk',name:'Milk',unit:'L'},{key:'buttermilk',name:'Buttermilk',unit:'L'},{key:'ghee',name:'Ghee',unit:'kg'},{key:'peda',name:'Peda',unit:'kg'},{key:'other',name:'Other',unit:'unit'}]}
function saleLabel(key){const p=saleProducts().find(x=>x.key===key);return p?p.name:key}
function getSaleRate(key){ensureSalesConfig();return num(db.settings.salePrices[key])}
function setSaleRate(key,rate){ensureSalesConfig();db.settings.salePrices[key]=num(rate);save()}
function customerRateFor(c,key,date){if(!c)return getSaleRate(key);const h=(c.priceHistory||[]).filter(x=>x.productKey===key||(!x.productKey&&c.saleKey===key)).sort((a,b)=>String(a.date).localeCompare(String(b.date)));let rate=num(c.rate);for(const x of h){if(String(x.date)<=String(date))rate=num(x.rate)}return rate||getSaleRate(key)}
function addCustomerPriceHistory(c,key,date,rate){c.priceHistory=c.priceHistory||[];c.priceHistory.push({id:uid(),productKey:key,date,rate:num(rate)});c.priceHistory.sort((a,b)=>String(a.date).localeCompare(String(b.date)))}
function save(){ensureSalesConfig();localStorage.setItem(KEY,JSON.stringify(db));scheduleCloudSync()}
function user(){return db.users.find(u=>u.id===db.currentUser)}
function audit(action,entity,recordId,before=null,after=null){db.audit.push({id:uid(),at:new Date().toISOString(),userId:user()?.id||'system',userName:user()?.name||'System',action,entity,recordId,before,after});save()}
function allowed(role,feature){if(role==='Owner'||role==='Full Access Member')return true;if(role==='Manager')return !['users','cashSettings'].includes(feature);if(role==='Family Member')return ['home','expenses','reports','sales','collections'].includes(feature);if(role==='Staff')return ['sales','collections','milk','stock','customers'].includes(feature);return false}
async function init(){
  if(!db.currentUser){login();return;}
  if(CLOUD_API){
    await cloudSync();
    render('dashboard');
    startCloudRealtimeSync();
  }else render('dashboard');
}
function login(){const options=db.users.filter(u=>u.active).map(u=>'<option value="'+u.id+'">'+esc(u.name)+' • '+esc(u.role)+'</option>').join('');document.getElementById('root').innerHTML='<div class="login"><div class="loginbox"><h1>Durga Dairy</h1><p>Online Management System</p><div class="notice">Sign in with your own account. Every entry is recorded with the member name and time.</div><div class="field"><label>Login</label><select id="loginUser">'+options+'</select></div><div class="field"><label>Password / PIN</label><input id="loginPin" type="password" autocomplete="current-password" placeholder="Password"></div><button class="btn" style="width:100%;margin-top:16px" onclick="doLogin()">Login</button><button class="linkbtn" onclick="forgotPassword()">Forgot Password?</button><p class="small">First-run demo: Hiren 1234 • Brother 3333 • Family 1111 • Staff 2222</p></div></div>'}
function forgotPassword(){modal('Forgot Password','<p class="muted">Enter your account email. In production this will send a secure reset link.</p><div class="field"><label>Email</label><input id="resetEmail" type="email" placeholder="you@example.com"></div>',async()=>{const email=val('resetEmail');if(!email)return alert('Email required.');if(CLOUD_API){try{const r=await fetch(CLOUD_API.replace(/\/$/, '')+'/api/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});alert(r.ok?'If the account exists, a reset link has been sent.':'Reset request failed.')}catch(e){alert('Reset service unavailable.')}}else alert('Password reset is ready for cloud deployment; connect the online API to send the secure reset link.');closeModal()})}
async function doLogin(){const id=document.getElementById('loginUser').value,p=document.getElementById('loginPin').value,u=db.users.find(x=>x.id===id);if(!u||u.pin!==p)return alert('Wrong password.');if(CLOUD_API){try{const r=await fetch(CLOUD_API.replace(/\/$/, '')+'/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:u.email,password:p,workspaceId:'durga-dairy'})});if(r.ok){const j=await r.json();localStorage.setItem('durga-token',j.token||'')}}catch(e){cloudState={status:'offline',error:e.message}}}db.currentUser=id;save();audit('LOGIN','session',id,null,{name:u.name});render('dashboard');cloudSync()}
function navItems(){return [['dashboard','⌂ Dashboard'],['sales','▣ Daily Sale'],['collections','▤ Bill Collection'],['milk','🥛 Milk Purchase'],['stock','▦ Stock Purchase'],['expenses','₹ Expense'],['customers','♙ Customers'],['vendors','▤ Vendors'],['cash','◉ Cash Flow'],['reports','▥ Reports'],['audit','◌ Activity Log'],['backup','☁ Online Backup'],['users','♙ Members']].filter(([k])=>allowed(user()?.role,k)||k==='dashboard'||k==='audit')}
function shell(active,body,title){document.getElementById('root').innerHTML=`<div class="app"><aside class="sidebar" id="side"><div class="brand">🐄 Durga Dairy<small>Management System</small></div><div class="nav">${navItems().map(([k,t])=>`<button class="${active===k?'active':''}" onclick="render('${k}');closeSide()">${t}</button>`).join('')}</div><div style="position:absolute;bottom:15px;left:12px;right:12px"><button class="nav" style="width:100%;border:0;background:#ffffff12;color:#fff;padding:10px;border-radius:8px" onclick="logout()">↪ Logout</button></div></aside><section class="main"><header class="topbar"><div style="display:flex;align-items:center;gap:10px"><button class="menuBtn" onclick="toggleSide()">☰</button><b>${title||'Dashboard'}</b></div><div class="right"><span class="pill green">● Cloud / Local</span><span class="workspace">Durga Dairy</span><span class="avatar">${esc((user()?.name||'?')[0])}</span><span class="small">${esc(user()?.name||'')}</span></div></header><main class="page">${body}<div class="footer">Durga Dairy Management • Online + Offline prototype • Logged in as ${esc(user()?.name||'')}</div></main></section></div>`;if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{})}
function toggleSide(){document.getElementById('side')?.classList.toggle('open')}function closeSide(){document.getElementById('side')?.classList.remove('open')}
function modal(title,body,saveFn){document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div class="modalbox"><div class="modalhead"><h3>${title}</h3><button class="x" onclick="closeModal()">×</button></div>${body}<div class="actions"><button class="btn gray" onclick="closeModal()">Cancel</button><button class="btn" id="modalSave">Save</button></div></div></div>`);document.getElementById('modalSave').onclick=saveFn}
function closeModal(){document.getElementById('modal')?.remove()}
function metric(label,value,sub=''){return `<div class="card metric"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function monthTotal(arr,m,key='amount'){return arr.filter(x=>ym(x.date)===m).reduce((a,x)=>a+num(x[key]),0)}
function dashboard(){const m=ym(iso());const sales=monthTotal(db.sales,m),collections=monthTotal(db.collections,m),expenses=monthTotal(db.expenses,m),milkCost=monthTotal(db.milk,m,'total'),stockCost=monthTotal(db.stockPurchases,m,'total');const cashIn=sales+collections, cashOut=expenses+db.milk.filter(x=>ym(x.date)===m).reduce((a,x)=>a+num(x.paid),0)+db.stockPurchases.filter(x=>ym(x.date)===m).reduce((a,x)=>a+num(x.paid),0);const lastCheck=[...db.cashChecks].sort((a,b)=>b.date.localeCompare(a.date))[0];const expected=(lastCheck?num(lastCheck.actual):0)+cashIn-cashOut;const actual=lastCheck?num(lastCheck.actual):0;const diff=actual?actual-expected:0;const products=productStats(m);shell('dashboard',`<div class="sectionhead"><div><h1 style="margin:0">Good morning, ${esc(user()?.name||'')}</h1><div class="muted">Today ${iso()} • ${esc(user()?.role||'')}</div></div><div class="toolbar"><button class="btn green" onclick="quick('sale')">+ Daily Sale</button><button class="btn" onclick="quick('expense')">+ Expense</button><button class="btn orange" onclick="quick('milk')">+ Milk Purchase</button><button class="btn gray" onclick="quick('stock')">+ Stock Purchase</button></div></div><div class="grid">${metric('Sales This Month',money(sales))}${metric('Customer Collection',money(collections))}${metric('Milk Purchase',money(milkCost))}${metric('Expenses',money(expenses))}</div><div class="grid" style="margin-top:14px">${metric('Stock Purchase',money(stockCost))}${metric('Expected Cash',money(expected),'Calculated')}${metric('Actual Cash',actual?money(actual):'Not checked','Manual cash check')}${metric('Cash Difference',actual?money(diff):'—',actual?(diff===0?'Matched':'Needs reconciliation'):'Enter month-end cash')}</div><div class="charts section"><div class="card"><div class="sectionhead"><h2>Sales by Product</h2><span class="muted">${m}</span></div>${productBars(products)}</div><div class="card"><div class="sectionhead"><h2>Profit by Product</h2></div>${profitBars(products)}</div><div class="card"><div class="sectionhead"><h2>Sales Mix</h2></div><div class="donut"></div><div class="legend">${products.map(p=>`<span><b>${esc(p.name)}</b><span>${p.salesPct.toFixed(1)}%</span></span>`).join('')}</div></div></div><div class="card section"><div class="sectionhead"><h2>Product Performance</h2><button class="btn sm gray" onclick="render('reports')">Full Report</button></div>${productTable(products)}</div>`)}
function productStats(m){const names=['Milk','Ghee','Peda','Buttermilk','Other'];return names.map(name=>{const sales=db.sales.filter(x=>ym(x.date)===m&&x.product===name);const saleAmt=sales.reduce((a,x)=>a+num(x.amount),0),qty=sales.reduce((a,x)=>a+num(x.qty),0);let cost=0;if(name==='Milk')cost=db.milk.filter(x=>ym(x.date)===m).reduce((a,x)=>a+num(x.total),0);if(name==='Ghee')cost=db.stockPurchases.filter(x=>ym(x.date)===m&&x.item==='Ghee').reduce((a,x)=>a+num(x.total),0);if(name==='Peda')cost=db.stockPurchases.filter(x=>ym(x.date)===m&&x.item==='Peda').reduce((a,x)=>a+num(x.total),0);if(name==='Buttermilk')cost=saleAmt*.29;const profit=saleAmt-cost;return{name,saleAmt,qty,cost,profit,margin:saleAmt?profit/saleAmt*100:0,salesPct:0}}).map((p,_,a)=>{const total=a.reduce((s,x)=>s+x.saleAmt,0);p.salesPct=total?p.saleAmt/total*100:0;return p})}
function productBars(ps){const max=Math.max(1,...ps.map(x=>x.saleAmt));return `<div class="chartbar">${ps.map(p=>`<div class="bar" style="height:${Math.max(8,p.saleAmt/max*140)}px;background:${p.name==='Ghee'?'#f2b84b':p.name==='Milk'?'#58a9e5':p.name==='Peda'?'#9a79dc':p.name==='Buttermilk'?'#52b98e':'#e67b7b'}"><span>${esc(p.name)}</span></div>`).join('')}</div>`}
function profitBars(ps){const max=Math.max(1,...ps.map(x=>Math.max(0,x.profit)));return `<div class="chartbar">${ps.map(p=>`<div class="bar" style="height:${Math.max(8,Math.max(0,p.profit)/max*140)}px;background:${p.margin>=60?'#0f9d6e':'#79bce9'}"><span>${p.margin.toFixed(0)}%</span></div>`).join('')}</div><div class="muted">Height = profit contribution • label = margin %</div>`}
function productTable(ps){return `<div class="tablewrap"><table class="table"><tr><th>Product</th><th>Qty Sold</th><th>Sales</th><th>Cost</th><th>Profit</th><th>Margin %</th><th>Sales %</th></tr>${ps.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${p.qty||'—'}</td><td>${money(p.saleAmt)}</td><td>${money(p.cost)}</td><td class="kpiGood"><b>${money(p.profit)}</b></td><td><span class="pill ${p.margin>=50?'green':'orange'}">${p.margin.toFixed(1)}%</span></td><td>${p.salesPct.toFixed(1)}%</td></tr>`).join('')}</table></div>`}
function quick(type){if(type==='sale')addSale();if(type==='expense')addExpense();if(type==='milk')addMilk();if(type==='stock')addStock()}
function addSale(preKey=''){ensureSalesConfig();const products=saleProducts(),initial=products.find(p=>p.key===preKey)||products[0];modal('Daily Sale • Bulk Entry',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Product</label><select id="productKey" onchange="saleProductChanged()">${products.map(p=>`<option value="${p.key}" ${p.key===initial.key?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Selling Rate ₹</label><input id="rate" type="number" step="0.01" value="${getSaleRate(initial.key)}" oninput="saleAmountChanged()"><div class="muted">Bulk Daily Sale rate.</div></div><div class="field"><label>Quantity</label><input id="qty" type="number" step="0.01" oninput="saleAmountChanged()"></div><div class="field"><label>Total Sale ₹</label><input id="amount" type="number" step="0.01" value="0"></div><div class="field span2"><label>Description / Other Detail</label><input id="desc" placeholder="For Other: e.g. 30 L bulk milk"></div><div class="field span4"><div class="notice">Daily Saleમાં Customer Name રાખવામાં આવતું નથી. આ section માત્ર દિવસના bulk sales માટે છે.</div></div></div>`,()=>{const key=val('productKey'),p=products.find(x=>x.key===key)||initial,date=val('date'),r={id:uid(),date,product:p.name,saleKey:key,customerId:'',customerName:'',qty:num(val('qty')),rate:num(val('rate')),amount:num(val('amount')),description:val('desc')};if(!r.amount&&r.qty&&r.rate)r.amount=r.qty*r.rate;if(!r.amount)return alert('Enter quantity/rate or total sale amount.');db.sales.push(r);audit('CREATE','Daily Sale',r.id,null,r);save();closeModal();render('sales')});saleProductChanged()}
function saleProductChanged(){const key=val('productKey'),r=document.getElementById('rate');if(r)r.value=getSaleRate(key);saleAmountChanged()}
function saleProductChanged(){saleCustomerChanged()}
function saleCustomerChanged(){const cid=val('customerId'),c=(db.customers||[]).find(x=>x.id===cid),key=val('productKey'),date=val('date')||iso(),r=document.getElementById('rate');if(r)r.value=c?customerRateFor(c,key,date):getSaleRate(key);saleAmountChanged()}
function saleAmountChanged(){const q=num(val('qty')),r=num(val('rate')),a=document.getElementById('amount');if(a&&q&&r)a.value=(q*r).toFixed(2)}

function addCollection(){modal('Bill Collection',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Mode</label><select id="mode"><option>Customer-wise</option><option>Bulk Collection</option></select></div><div class="field span2"><label>Customer / Description</label><input id="name" placeholder="Customer name or bulk note"></div><div class="field"><label>Amount ₹</label><input id="amount" type="number"></div><div class="field"><label>Payment Mode</label><select id="pay"><option>Cash</option><option>UPI</option><option>Bank</option><option>Other</option></select></div></div>`,()=>{const r={id:uid(),date:val('date'),mode:val('mode'),name:val('name'),amount:num(val('amount')),paymentMode:val('pay')};if(!r.amount)return alert('Enter amount.');db.collections.push(r);audit('CREATE','Bill Collection',r.id,null,r);save();closeModal();render('collections')})}
function addExpense(){modal('Add Expense',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Category</label><select id="cat"><option>Home</option><option>Fixed / Utility</option><option>EMI</option><option>Hospital</option><option>Car</option><option>Bike</option><option>Grocery</option><option>Fuel</option><option>Dairy Expense</option><option>Other</option></select></div><div class="field"><label>Amount ₹</label><input id="amount" type="number"></div><div class="field"><label>Payment Mode</label><select id="pay"><option>Cash</option><option>UPI</option><option>Bank</option><option>Other</option></select></div><div class="field span4"><label>Description ${val('cat')==='Home'?'(mandatory)':''}</label><textarea id="desc" placeholder="Where / what was the expense?"></textarea></div></div>`,()=>{const r={id:uid(),date:val('date'),category:val('cat'),amount:num(val('amount')),paymentMode:val('pay'),description:val('desc')};if(!r.amount||!r.description&&r.category==='Home')return alert('Amount and Home description are required.');db.expenses.push(r);audit('CREATE','Expense',r.id,null,r);save();closeModal();render('expenses')})}
function addMilk(){modal('Daily Milk Purchase • Cow + Buffalo',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Vendor</label><input id="vendor" placeholder="Vendor name"></div><div class="field"><label>Cow Litres</label><input id="cow" type="number" step="0.01"></div><div class="field"><label>Cow Rate ₹/L</label><input id="cowRate" type="number" step="0.01" value="${db.settings.cowRate}"></div><div class="field"><label>Buffalo Litres</label><input id="buff" type="number" step="0.01"></div><div class="field"><label>Buffalo Rate ₹/L</label><input id="buffRate" type="number" step="0.01" value="${db.settings.buffaloRate}"></div><div class="field"><label>Paid Now ₹</label><input id="paid" type="number" value="0"></div><div class="field"><label>Effective Rate Change?</label><select id="change"><option value="no">No, use current</option><option value="yes">Yes, save this rate from this date</option></select></div><div class="field span4"><div class="notice">Rates are date-based. Changing a rate here never rewrites older purchases. If you enter a new rate for a date, that rate applies from that date forward until another rate change is entered.</div></div></div>`,()=>{const r={id:uid(),date:val('date'),vendor:val('vendor'),cowLitres:num(val('cow')),cowRate:num(val('cowRate')),buffLitres:num(val('buff')),buffRate:num(val('buffRate')),paid:num(val('paid'))};r.total=r.cowLitres*r.cowRate+r.buffLitres*r.buffRate;r.balance=r.total-r.paid;if(!r.cowLitres&&!r.buffLitres)return alert('Enter cow or buffalo litres.');if(val('change')==='yes'){db.settings.cowRate=r.cowRate;db.settings.buffaloRate=r.buffRate;db.prices.push({id:uid(),date:r.date,cowRate:r.cowRate,buffaloRate:r.buffRate,createdBy:user().name})}db.milk.push(r);audit('CREATE','Milk Purchase',r.id,null,r);save();closeModal();render('milk')})}
function addStock(){modal('Stock Purchase • Ghee / Peda / Other',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Item</label><select id="item"><option>Ghee</option><option>Peda</option><option>Other</option></select></div><div class="field"><label>Quantity</label><input id="qty" type="number" step="0.01"></div><div class="field"><label>Unit</label><select id="unit"><option>kg</option><option>litre</option><option>piece</option></select></div><div class="field"><label>Purchase Rate</label><input id="rate" type="number" step="0.01" value="${db.settings.gheeBuyRate}"></div><div class="field"><label>Paid Now ₹</label><input id="paid" type="number" value="0"></div><div class="field"><label>Stock Until (optional)</label><input id="until" type="date"></div><div class="field"><label>Vendor</label><input id="vendor"></div><div class="field span4"><div class="notice">Purchase price is saved with this dated transaction. A future price change can be entered with its effective date and will not change old purchases.</div></div></div>`,()=>{const r={id:uid(),date:val('date'),item:val('item'),qty:num(val('qty')),unit:val('unit'),rate:num(val('rate')),paid:num(val('paid')),stockUntil:val('until'),vendor:val('vendor')};r.total=r.qty*r.rate;r.balance=r.total-r.paid;if(!r.qty||!r.rate)return alert('Enter quantity and purchase rate.');db.stockPurchases.push(r);if(r.item==='Ghee')db.settings.gheeBuyRate=r.rate;if(r.item==='Peda')db.settings.pedaBuyRate=r.rate;audit('CREATE','Stock Purchase',r.id,null,r);save();closeModal();render('stock')})}
function addUsage(){modal('Stock Usage / Sale Adjustment',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Item</label><select id="item"><option>Ghee</option><option>Peda</option><option>Other</option></select></div><div class="field"><label>Quantity Used / Sold</label><input id="qty" type="number" step="0.01"></div><div class="field span2"><label>Description</label><input id="desc" placeholder="Stock used/sold"></div></div>`,()=>{const r={id:uid(),date:val('date'),item:val('item'),qty:num(val('qty')),description:val('desc')};if(!r.qty)return alert('Enter quantity.');db.stockUsage.push(r);audit('CREATE','Stock Usage',r.id,null,r);save();closeModal();render('stock')})}
function addCustomer(){modal('Add Customer',`<div class="formgrid"><div class="field span2"><label>Customer Name</label><input id="name"></div><div class="field"><label>Mobile Number</label><input id="mobile"></div><div class="field span2"><label>Address</label><input id="address"></div><div class="field"><label>Product</label><select id="productKey"><option value="milk">Milk</option><option value="buttermilk">Buttermilk</option><option value="ghee">Ghee</option><option value="peda">Peda</option></select></div><div class="field"><label>Selling Price ₹</label><input id="rate" type="number" step="0.01"></div><div class="field"><label>Effective From</label><input id="effectiveDate" type="date" value="${iso()}"></div><div class="field"><label>Status</label><select id="active"><option value="true">Active</option><option value="false">Inactive</option></select></div></div>`,()=>{const name=val('name').trim();if(!name)return alert('Enter customer name.');if((db.customers||[]).some(x=>String(x.name).trim().toLowerCase()===name.toLowerCase()))return alert('Customer name already exists.');const key=val('productKey'),date=val('effectiveDate')||iso(),rate=num(val('rate'));const r={id:uid(),name,mobile:val('mobile'),address:val('address'),product:saleProducts().find(x=>x.key===key)?.name||'Milk',saleKey:key,active:val('active')!=='false',priceHistory:[{id:uid(),productKey:key,date,rate}],createdAt:new Date().toISOString()};db.customers.push(r);audit('CREATE','Customer',r.id,null,r);save();closeModal();render('customers')})}
function editCustomer(id){const c=(db.customers||[]).find(x=>x.id===id);if(!c)return;const key=c.saleKey||'milk',rate=customerRateFor(c,key,iso());modal('Edit Customer',`<div class="formgrid"><div class="field span2"><label>Customer Name</label><input value="${esc(c.name||'')}" readonly></div><div class="field"><label>Mobile Number</label><input id="mobile" value="${esc(c.mobile||'')}"></div><div class="field span2"><label>Address</label><input id="address" value="${esc(c.address||'')}"></div><div class="field"><label>Product</label><select id="productKey">${saleProducts().filter(p=>p.key!=='other').map(p=>`<option value="${p.key}" ${p.key===key?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>New Selling Price ₹</label><input id="rate" type="number" step="0.01" value="${rate}"></div><div class="field"><label>Effective From</label><input id="effectiveDate" type="date" value="${iso()}"></div><div class="field"><label>Status</label><select id="active"><option value="true" ${c.active!==false?'selected':''}>Active</option><option value="false" ${c.active===false?'selected':''}>Inactive</option></select></div></div>`,()=>{c.mobile=val('mobile');c.address=val('address');const nk=val('productKey'),nd=val('effectiveDate')||iso(),nr=num(val('rate'));c.saleKey=nk;c.product=saleProducts().find(x=>x.key===nk)?.name||c.product;c.active=val('active')!=='false';addCustomerPriceHistory(c,nk,nd,nr);audit('UPDATE','Customer',c.id,null,c);save();closeModal();render('customers')})}
function addVendor(){modal('Vendor',`<div class="formgrid"><div class="field span2"><label>Name</label><input id="name"></div><div class="field"><label>Type</label><select id="type"><option>Milk</option><option>Ghee</option><option>Peda</option><option>Other</option></select></div><div class="field"><label>Phone</label><input id="phone"></div></div>`,()=>{const r={id:uid(),name:val('name'),type:val('type'),phone:val('phone')};if(!r.name)return alert('Enter vendor name.');db.vendors.push(r);audit('CREATE','Vendor',r.id,null,r);save();closeModal();render('vendors')})}
function addCashCheck(){modal('Manual Cash Check',`<div class="formgrid"><div class="field"><label>Date</label><input id="date" type="date" value="${iso()}"></div><div class="field"><label>Actual Cash ₹</label><input id="actual" type="number"></div><div class="field span2"><label>Note</label><input id="note" placeholder="Physical cash count"></div></div>`,()=>{const r={id:uid(),date:val('date'),actual:num(val('actual')),note:val('note')};if(!r.actual)return alert('Enter actual cash.');db.cashChecks.push(r);audit('CREATE','Cash Check',r.id,null,r);save();closeModal();render('cash')})}
function val(id){return document.getElementById(id)?.value||''}
function tableRows(rows,cols,actions=true){return `<div class="tablewrap"><table class="table"><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}${actions?'<th>Action</th>':''}</tr>${rows.map(r=>`<tr>${cols.map(c=>`<td>${c[1](r)}</td>`).join('')}${actions?`<td><button class="btn sm gray" onclick="editGeneric('${r._entity}','${r.id}')">Edit</button> <button class="btn sm red" onclick="deleteGeneric('${r._entity}','${r.id}')">Delete</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${cols.length+(actions?1:0)}" class="empty">No entries.</td></tr>`}</table></div>`}
function listWithEntity(arr,entity){return arr.map(x=>Object.assign({_entity:entity},x))}
function dateFilters(prefix,section){return `<div class="card" style="margin-bottom:12px"><div class="toolbar"><select id="${prefix}Mode" onchange="applySectionFilter('${section}','${prefix}')"><option value="all">All Dates</option><option value="month">Month</option><option value="year">Year</option><option value="date">Specific Date</option></select><input id="${prefix}Value" type="month" value="${ym(iso())}" onchange="applySectionFilter('${section}','${prefix}')"><button class="btn sm gray" onclick="document.getElementById('${prefix}Mode').value='all';document.getElementById('${prefix}Value').value='';applySectionFilter('${section}','${prefix}')">Clear</button></div></div>`}
function applySectionFilter(section,prefix){const mode=document.getElementById(prefix+'Mode')?.value||'all';const el=document.getElementById(prefix+'Value');if(el)el.type=mode==='date'?'date':mode==='year'?'number':'month';const value=el?.value||'';window['render'+section[0].toUpperCase()+section.slice(1)](mode,value)}

function renderSales(mode='all',value=''){ensureSalesConfig();const rows=listWithEntity([...db.sales].filter(x=>filterDate(x.date,mode,value)).sort((a,b)=>b.date.localeCompare(a.date)),'sales');const filtered=db.sales.filter(x=>filterDate(x.date,mode,value));const fixedFiltered=(db.customerSales||[]).filter(x=>filterDate(x.date,mode,value));const fixedTotal=fixedFiltered.reduce((a,x)=>a+num(x.amount),0);const summaries=saleProducts().map(p=>{const rr=filtered.filter(x=>(x.saleKey===p.key)||(p.key==='milk'&&!x.saleKey&&x.product==='Milk'));return {...p,qty:rr.reduce((a,x)=>a+num(x.qty),0),amt:rr.reduce((a,x)=>a+num(x.amount),0)}});const bulkGrand=summaries.reduce((a,x)=>a+x.amt,0),grand=bulkGrand+fixedTotal;const cards=summaries.map(p=>`<div class="card"><div class="sectionhead"><div><h3 style="margin:0">${esc(saleLabel(p.key))}</h3><div class="muted">${p.qty.toFixed(2)} ${p.unit} • ${money(p.amt)} sold</div></div><span class="pill green">Bulk Daily Sale</span></div><div class="toolbar"><button class="btn sm green" onclick="addSale('${p.key}')">+ Sale</button></div></div>`).join('');const report=`<div class="card section"><div class="sectionhead"><div><h2 style="margin:0">Sales Report</h2><div class="muted">Selected ${mode==='all'?'all dates':mode==='date'?fmtDate(value):value}</div></div><span class="pill green">Grand Total ${money(grand)}</span></div><table><thead><tr><th>Product</th><th>Quantity</th><th>Sales Amount</th></tr></thead><tbody>${summaries.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${p.qty.toFixed(2)} ${p.unit}</td><td>${money(p.amt)}</td></tr>`).join('')}<tr><td><b>Bulk Sales Total</b></td><td>—</td><td><b>${money(bulkGrand)}</b></td></tr><tr><td><b>Fixed Customer Sales</b></td><td>—</td><td><b>${money(fixedTotal)}</b></td></tr><tr><td><b>GRAND TOTAL SALES</b></td><td>—</td><td><b>${money(grand)}</b></td></tr></tbody></table></div>`;shell('sales',`${dateFilters('salesFilter','sales')}<div class="sectionhead"><div><h1>Daily Sale</h1><div class="muted">Daily bulk sales only. Customer name is not part of Daily Sale.</div></div><button class="btn green" onclick="addSale()">+ Add Daily Sale</button></div><div class="grid">${cards}</div>${report}<div class="card section"><div class="sectionhead"><h2>Daily Sale Entries</h2></div>${tableRows(rows,[['Date',r=>fmtDate(r.date)],['Product',r=>`<span class="pill">${esc(r.product||'')}</span>`],['Qty',r=>r.qty||'—'],['Rate',r=>r.rate?money(r.rate):'—'],['Amount',r=>money(r.amount)],['Description',r=>esc(r.description||'')]])}</div>`,'Daily Sale')}function renderCollections(mode='all',value=''){const rows=listWithEntity([...db.collections].filter(x=>filterDate(x.date,mode,value)).sort((a,b)=>b.date.localeCompare(a.date)),'collections');const total=rows.reduce((a,r)=>a+r.amount,0);shell('collections',`${dateFilters('collectionFilter','collections')}<div class="sectionhead"><div><h1>Bill Collection</h1><div class="muted">Customer-wise or bulk collection</div></div><button class="btn" onclick="addCollection()">+ Add Collection</button></div><div class="grid">${metric('Total Recorded',money(total))}${metric('Customer-wise',money(rows.filter(x=>x.mode==='Customer-wise').reduce((a,x)=>a+x.amount,0)))}${metric('Bulk',money(rows.filter(x=>x.mode==='Bulk Collection').reduce((a,x)=>a+x.amount,0)))}${metric('Entries',rows.length)}</div><div class="section">${tableRows(rows,[['Date',r=>fmtDate(r.date)],['Mode',r=>r.mode],['Customer / Note',r=>esc(r.name)],['Amount',r=>money(r.amount)],['Payment',r=>r.paymentMode]])}</div>`,'Bill Collection')}
function renderMilk(mode='all',value=''){const rows=listWithEntity([...db.milk].filter(x=>filterDate(x.date,mode,value)).sort((a,b)=>b.date.localeCompare(a.date)),'milk');const m=ym(iso()),cow=rows.filter(x=>ym(x.date)===m).reduce((a,x)=>a+x.cowLitres,0),buff=rows.filter(x=>ym(x.date)===m).reduce((a,x)=>a+x.buffLitres,0);shell('milk',`${dateFilters('milkFilter','milk')}<div class="sectionhead"><div><h1>Daily Milk Purchase</h1><div class="muted">Cow + Buffalo • date-based rates</div></div><button class="btn orange" onclick="addMilk()">+ Add Milk Purchase</button></div><div class="grid">${metric('Cow This Month',cow.toFixed(2)+' L',money(rows.filter(x=>ym(x.date)===m).reduce((a,x)=>a+x.cowLitres*x.cowRate,0)))}${metric('Buffalo This Month',buff.toFixed(2)+' L',money(rows.filter(x=>ym(x.date)===m).reduce((a,x)=>a+x.buffLitres*x.buffRate,0)))}${metric('Total Milk', (cow+buff).toFixed(2)+' L')}${metric('Current Rates',`Cow ₹${db.settings.cowRate} • Buffalo ₹${db.settings.buffaloRate}`)}</div><div class="sectionhead"><h2>Purchase History</h2></div>${tableRows(rows,[['Date',r=>fmtDate(r.date)],['Vendor',r=>esc(r.vendor||'')],['Cow',r=>`${r.cowLitres} L × ${money(r.cowRate)}`],['Buffalo',r=>`${r.buffLitres} L × ${money(r.buffRate)}`],['Total',r=>money(r.total)],['Paid',r=>money(r.paid)],['Balance',r=>money(r.balance)]])}<div class="section"><div class="card"><b>Price History</b><div class="muted" style="margin:6px 0">Only a dated rate change affects future entries. Older transactions keep their original rate.</div>${db.prices.sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<span class="pill" style="margin:3px">${p.date}: Cow ₹${p.cowRate}, Buffalo ₹${p.buffaloRate}</span>`).join('')||'<span class="muted">No explicit changes yet.</span>'}</div></div>`,'Milk Purchase')}
function stockTotals(item){return db.stockPurchases.filter(x=>x.item===item).reduce((a,x)=>a+x.qty,0)-db.stockUsage.filter(x=>x.item===item).reduce((a,x)=>a+x.qty,0)}
function renderStock(mode='all',value=''){const rows=listWithEntity([...db.stockPurchases].filter(x=>filterDate(x.date,mode,value)).sort((a,b)=>b.date.localeCompare(a.date)),'stockPurchases');shell('stock',`${dateFilters('stockFilter','stock')}<div class="sectionhead"><div><h1>Stock Purchase & Stock</h1><div class="muted">Ghee/Peda are purchased when needed. Usage carries into future months.</div></div><div class="toolbar"><button class="btn" onclick="addStock()">+ Stock Purchase</button><button class="btn gray" onclick="addUsage()">+ Stock Usage / Sale</button></div></div><div class="grid">${metric('Ghee Stock',stockTotals('Ghee').toFixed(2)+' kg')}${metric('Peda Stock',stockTotals('Peda').toFixed(2)+' kg')}${metric('Other Stock',stockTotals('Other').toFixed(2))}${metric('Current Ghee Buy Rate',money(db.settings.gheeBuyRate)+'/kg')}</div>${tableRows(rows,[['Date',r=>fmtDate(r.date)],['Item',r=>r.item],['Qty',r=>`${r.qty} ${r.unit}`],['Rate',r=>money(r.rate)],['Total',r=>money(r.total)],['Paid',r=>money(r.paid)],['Balance',r=>money(r.balance)],['Vendor',r=>esc(r.vendor||'')]])}<div class="sectionhead"><h2>Stock Usage History</h2></div>${tableRows(listWithEntity([...db.stockUsage].sort((a,b)=>b.date.localeCompare(a.date)),'stockUsage'),[['Date',r=>fmtDate(r.date)],['Item',r=>r.item],['Qty',r=>r.qty],['Description',r=>esc(r.description||'')]])}`,'Stock Purchase')}
function renderExpenses(mode='all',value=''){const rows=listWithEntity([...db.expenses].filter(x=>filterDate(x.date,mode,value)).sort((a,b)=>b.date.localeCompare(a.date)),'expenses');const total=rows.reduce((a,x)=>a+x.amount,0);shell('expenses',`${dateFilters('expenseFilter','expenses')}<div class="sectionhead"><div><h1>Expenses</h1><div class="muted">Home, utility, EMI, hospital, car, bike and dairy expenses</div></div><button class="btn red" onclick="addExpense()">+ Add Expense</button></div><div class="grid">${metric('Total Expenses',money(total))}${metric('Home',money(rows.filter(x=>x.category==='Home').reduce((a,x)=>a+x.amount,0)))}${metric('Dairy Expense',money(rows.filter(x=>x.category==='Dairy Expense').reduce((a,x)=>a+x.amount,0)))}${metric('Other',money(rows.filter(x=>!['Home','Dairy Expense'].includes(x.category)).reduce((a,x)=>a+x.amount,0)))}</div>${tableRows(rows,[['Date',r=>fmtDate(r.date)],['Category',r=>r.category],['Amount',r=>money(r.amount)],['Description',r=>esc(r.description||'')],['Payment',r=>r.paymentMode]])}`,'Expenses')}

function customerMonths(id){const ms=new Set();(db.customerSales||[]).filter(x=>x.customerId===id).forEach(x=>ms.add(ym(x.date)));(db.customerPayments||[]).filter(x=>x.customerId===id).forEach(x=>ms.add(x.month));return [...ms].filter(Boolean).sort().reverse()}
function customerMonthSummary(id,month){const sales=(db.customerSales||[]).filter(x=>x.customerId===id&&ym(x.date)===month),bill=sales.reduce((a,x)=>a+num(x.amount),0),qty=sales.reduce((a,x)=>a+num(x.qty),0),pay=(db.customerPayments||[]).filter(x=>x.customerId===id&&x.month===month),paid=pay.reduce((a,x)=>a+num(x.amount),0),adjust=pay.reduce((a,x)=>a+num(x.adjustment),0);return{month,qty,bill,paid,adjust,balance:Math.max(0,bill-paid-adjust),status:bill>0&&paid+adjust>=bill?'Paid':'Pending'}}
function customerAging(c){const sums=customerMonths(c.id).map(m=>customerMonthSummary(c.id,m)),unpaid=sums.filter(x=>x.bill>0&&x.balance>0);return{unpaidCount:unpaid.length,outstanding:unpaid.reduce((a,x)=>a+x.balance,0),current:sums.find(x=>x.month===ym(iso()))||{bill:0,paid:0,adjust:0,balance:0,qty:0}}}
function customerDailyExisting(customerId,date){return (db.customerSales||[]).find(x=>x.customerId===customerId&&x.date===date&&x.productKey==='milk')}
function editCustomerDailyMilk(id){
  const r=(db.customerSales||[]).find(x=>x.id===id);if(!r)return;
  const cust=(db.customers||[]).find(x=>x.id===r.customerId);
  modal('Edit Date-wise Milk Entry','<div class="formgrid"><div class="field span2"><label>Customer</label><input value="'+esc(cust?.name||r.customerName||'')+'" readonly></div><div class="field"><label>Date</label><input id="editMilkDate" type="date" value="'+r.date+'"></div><div class="field"><label>Rate ₹ / L</label><input id="editMilkRate" type="number" step="0.01" value="'+num(r.rate)+'"></div><div class="field"><label>Morning (L)</label><input id="editMilkMorning" type="number" step="0.01" value="'+num(r.morningQty)+'"></div><div class="field"><label>Evening (L)</label><input id="editMilkEvening" type="number" step="0.01" value="'+num(r.eveningQty)+'"></div><div class="field span2"><label>Total</label><input id="editMilkTotal" value="'+num(r.qty).toFixed(2)+' L" readonly></div></div>',()=>{
    const date=val('editMilkDate'),mq=num(val('editMilkMorning')),eq=num(val('editMilkEvening')),rate=num(val('editMilkRate')),qty=mq+eq;
    if(!date)return alert('Date required.');
    if(!mq&&!eq){if(!confirm('Both Morning and Evening are zero. Delete this entry?'))return;db.customerSales=db.customerSales.filter(x=>x.id!==id);audit('DELETE','Customer Daily Sale',id,r,null);save();closeModal();editCustomerEntries(r.customerId);return}
    const duplicate=customerDailyExisting(r.customerId,date);
    if(duplicate&&duplicate.id!==id)return alert('An entry already exists for this customer on '+fmtDate(date)+'. Edit that entry instead.');
    r.date=date;r.morningQty=mq;r.eveningQty=eq;r.qty=qty;r.rate=rate;r.amount=qty*rate;
    audit('UPDATE','Customer Daily Sale',r.id,null,r);save();closeModal();editCustomerEntries(r.customerId);
  });
}
function deleteCustomerDailyMilk(id){
  const r=(db.customerSales||[]).find(x=>x.id===id);if(!r)return;
  if(!confirm('Delete milk entry for '+fmtDate(r.date)+'?'))return;
  db.customerSales=db.customerSales.filter(x=>x.id!==id);audit('DELETE','Customer Daily Sale',id,r,null);save();editCustomerEntries(r.customerId);
}
function saveCustomerDailyInline(customerId,date){const c=(db.customers||[]).find(x=>x.id===customerId);if(!c)return;const mq=num(document.getElementById('mq_'+customerId)?.value),eq=num(document.getElementById('eq_'+customerId)?.value),rate=customerRateFor(c,'milk',date),qty=mq+eq,amount=qty*rate;let r=customerDailyExisting(customerId,date);if(!mq&&!eq){if(r){db.customerSales=db.customerSales.filter(x=>x.id!==r.id);audit('DELETE','Customer Daily Sale',r.id,r,null);save()}return}if(r){r.morningQty=mq;r.eveningQty=eq;r.qty=qty;r.rate=rate;r.amount=amount;audit('UPDATE','Customer Daily Sale',r.id,null,r)}else{r={id:uid(),customerId,date,productKey:'milk',product:'Milk',morningQty:mq,eveningQty:eq,qty,rate,amount,note:''};db.customerSales.push(r);audit('CREATE','Customer Daily Sale',r.id,null,r)}save();renderCustomerDailyMilk(date)}
function changeCustomerStatus(id){const c=(db.customers||[]).find(x=>x.id===id);if(!c)return;c.active=c.active===false;audit('UPDATE','Customer Status',c.id,null,{active:c.active});save();render('customers')}
function renderCustomerDailyMilk(date=iso()){const d=date||iso(),customers=[...(db.customers||[])].filter(c=>c.active!==false).sort((a,b)=>String(a.name).localeCompare(String(b.name)));const rows=customers.map(c=>{const x=customerDailyExisting(c.id,d),rate=customerRateFor(c,'milk',d);return '<tr><td><button class="linkbtn" style="margin:0;text-align:left" onclick="renderCustomerLedger(\''+c.id+'\')"><b>'+esc(c.name)+'</b></button></td><td>'+esc(c.mobile||'')+'</td><td><input id="mq_'+c.id+'" class="inlineQty" type="number" step="0.01" value="'+(x?.morningQty||'')+'" onblur="saveCustomerDailyInline(\''+c.id+'\',\''+d+'\')"></td><td><input id="eq_'+c.id+'" class="inlineQty" type="number" step="0.01" value="'+(x?.eveningQty||'')+'" onblur="saveCustomerDailyInline(\''+c.id+'\',\''+d+'\')"></td><td><b>'+(x?.qty||0)+'</b></td><td>'+money(x?.rate||rate)+'</td><td>'+money(x?.amount||0)+'</td><td>'+(x?'<button class="btn sm gray" onclick="editCustomerDailyMilk(\''+x.id+'\')">Edit</button> <button class="btn sm red" onclick="deleteCustomerDailyMilk(\''+x.id+'\')">Delete</button>':'<span class="muted">Direct Entry</span>')+'</td></tr>'}).join('')||'<tr><td colspan="8" class="empty">No active customers.</td></tr>';shell('customers','<div class="sectionhead"><div><h1>Daily Milk Entry</h1><div class="muted">Selected date: '+fmtDate(d)+'. Morning and Evening can be entered directly.</div></div><div class="toolbar"><input id="dailyMilkDate" type="date" value="'+d+'" onchange="renderCustomerDailyMilk(this.value)"><button class="btn gray" onclick="render(\'customers\')">Back to Customers</button></div></div><div class="card section"><div class="sectionhead"><h2>Daily Milk Master</h2><div class="muted">Enter quantity directly. Existing entry can still be edited or deleted.</div></div><div class="tablewrap"><table class="table"><tr><th>Customer</th><th>Mobile</th><th>Morning</th><th>Evening</th><th>Total</th><th>Rate</th><th>Amount</th><th>Action</th></tr>'+rows+'</table></div></div>','Daily Milk Entry')}
function customerDailyProductChanged(){const c=(db.customers||[]).find(x=>x.id===window.__customerLedgerId),key=val('productKey'),r=document.getElementById('rate');if(c&&r)r.value=customerRateFor(c,key,val('date')||iso());customerDailyAmountChanged()}
